1	//! [`RegistryClient`] implementation that shells out to each ecosystem's own
2	//! publisher CLI (`cargo publish`, `npm publish`, `twine upload`) via
3	//! [`CommandRunner`], instead of talking to any registry's HTTP API
4	//! directly. This is a deliberate design constraint: registry HTTP protocols
5	//! are a moving target that the native tools already track for us, so we
6	//! never reimplement them here.
7	//!
8	//! [`PublishOrchestrator`](super::publish::PublishOrchestrator) is generic
9	//! over a single [`RegistryClient`] type, so this module exposes one
10	//! dispatching client ([`SubprocessRegistryClient`]) rather than three
11	//! separate types — it routes each call to the right ecosystem's command
12	//! construction/classification based on the [`PackageId`]'s ecosystem tag.
13	//!
14	//! ## Per-package publish metadata
15	//!
16	//! [`RegistryClient::publish`] only receives a [`PackageId`] and [`Version`].
17	//! To thread per-package metadata recorded in a
18	//! [`PublishPlan`](callisto_model::PublishPlan) entry — e.g.
19	//! `CratePublish::registry`, `NpmPublish::tag`/`access`, `PypiPublish::index`
20	//! — through this call boundary, callers **must** invoke
21	//! [`SubprocessRegistryClient::load_plan`] with the full plan before passing
22	//! the client to the orchestrator. The client stores the metadata in
23	//! per-ecosystem lookup maps keyed by package name and consults them at
24	//! dispatch time inside `RegistryClient::publish`.
25	
26	use std::collections::HashMap;
27	use std::path::PathBuf;
28	use std::time::Duration;
29	
30	use callisto_manifests::WorkspaceCargoResolver;
31	use callisto_model::{
32	    known_credential_env_values, normalize_pypi_package_name, redact_known_secrets, ApplyPermit, CommandOutput,
33	    CommandRunner, Ecosystem, NpmAccess, PackageId, PublishOutcome, RegistryClient, RegistryError, Version,
34	};
35	use toml;
36	
37	use super::publish::parse_retry_after;
38	
39	/// Maximum wall-clock time (in seconds) allowed for a single publish command
40	/// (`cargo publish`, `npm publish`, `twine upload`). If the process does not
41	/// exit within this window it is killed and the attempt is recorded as a
42	/// timeout failure.
43	const PUBLISH_TIMEOUT_SECS: u64 = 300;
44	
45	/// Per-package npm publish metadata stored in the metadata map.
46	struct NpmMeta {
47	    tag: Option<String>,
48	    access: Option<NpmAccess>,
49	    /// Private npm registry URL from `publishConfig.registry` in `package.json`.
50	    /// When `Some`, `--registry <url>` is appended to `npm publish` and
51	    /// `npm view`. When `None`, the public npm registry is used.
52	    registry: Option<String>,
53	}
54	
55	/// Dispatches [`RegistryClient`] calls to the right ecosystem CLI based on
56	/// each [`PackageId`]'s ecosystem tag.
57	///
58	/// Before calling through the [`RegistryClient`] trait, invoke
59	/// [`Self::load_plan`] so that per-package metadata (dist-tag, access level,
60	/// registry URL, private index URL, package directory) is threaded through to
61	/// the CLI args and working directory.
62	pub struct SubprocessRegistryClient<R: CommandRunner> {
63	    runner: R,
64	    /// Workspace root. Used as the base for resolving per-package directories
65	    /// and as the working directory for package managers that resolve packages
66	    /// by name from the workspace root (`cargo`, `pnpm`, `yarn`, `npm`).
67	    cwd: PathBuf,
68	    /// npm publish metadata keyed by package name.
69	    npm_meta: HashMap<String, NpmMeta>,
70	    /// Cargo registry name (e.g. `"my-private-registry"`) keyed by crate name.
71	    cargo_registry: HashMap<String, Option<String>>,
72	    /// Per-package directory (relative to workspace root) for Cargo crates.
73	    /// Used to read the on-disk `Cargo.toml` for a pre-publish version check.
74	    cargo_pkg_dir: HashMap<String, std::path::PathBuf>,
75	    /// Planned publish version per crate name, populated from the plan.
76	    cargo_planned_version: HashMap<String, Version>,
77	    /// PyPI index URL keyed by distribution name.
78	    pypi_index: HashMap<String, Option<String>>,
79	    /// Per-package directory (relative to workspace root) for npm packages,
80	    /// keyed by package name. Used for package managers that must be invoked
81	    /// from the package directory (bun).
82	    npm_pkg_dir: HashMap<String, PathBuf>,
83	    /// Per-package directory (relative to workspace root) for PyPI packages,
84	    /// keyed by distribution name. `twine upload` runs from this directory so
85	    /// that `dist/` resolves to the package's own dist directory in a monorepo.
86	    pypi_pkg_dir: HashMap<String, PathBuf>,
87	}
88	
89	impl<R: CommandRunner> SubprocessRegistryClient<R> {
90	    pub fn new(runner: R, cwd: PathBuf) -> Self {
91	        Self {
92	            runner,
93	            cwd,
94	            npm_meta: HashMap::new(),
95	            cargo_registry: HashMap::new(),
96	            cargo_pkg_dir: HashMap::new(),
97	            cargo_planned_version: HashMap::new(),
98	            pypi_index: HashMap::new(),
99	            npm_pkg_dir: HashMap::new(),
100	            pypi_pkg_dir: HashMap::new(),
101	        }
102	    }
103	
104	    /// Pre-loads per-package publish metadata from a [`callisto_model::PublishPlan`]
105	    /// so that `RegistryClient::publish` can thread the correct dist-tag,
106	    /// access level, registry, and private index URL through to each
107	    /// ecosystem CLI invocation. Must be called before any publish attempt
108	    /// that should respect plan-level overrides.
109	    pub fn load_plan(&mut self, plan: &callisto_model::PublishPlan) {
110	        for pkg in &plan.npm_platform_packages {
111	            self.npm_meta.insert(
112	                pkg.name.clone(),
113	                NpmMeta {
114	                    tag: pkg.tag.clone(),
115	                    access: pkg.access,
116	                    registry: pkg.registry.clone(),
117	                },
118	            );
119	            self.npm_pkg_dir.insert(pkg.name.clone(), pkg.package_dir.clone());
120	        }
121	        for pkg in &plan.npm_main_packages {
122	            self.npm_meta.insert(
123	                pkg.name.clone(),
124	                NpmMeta {
125	                    tag: pkg.tag.clone(),
126	                    access: pkg.access,
127	                    registry: pkg.registry.clone(),
128	                },
129	            );
130	            self.npm_pkg_dir.insert(pkg.name.clone(), pkg.package_dir.clone());
131	        }
132	        for pkg in &plan.rust_crates {
133	            self.cargo_registry.insert(pkg.name.clone(), pkg.registry.clone());
134	            self.cargo_planned_version.insert(pkg.name.clone(), pkg.version.clone());
135	            if let Some(dir) = &pkg.package_dir {
136	                self.cargo_pkg_dir.insert(pkg.name.clone(), dir.clone());
137	            }
138	        }
139	        for pkg in &plan.pypi_packages {
140	            self.pypi_index.insert(pkg.name.clone(), pkg.index.clone());
141	            self.pypi_pkg_dir.insert(pkg.name.clone(), pkg.package_dir.clone());
142	        }
143	    }
144	
145	    fn run(&self, program: &str, args: &[&str]) -> Result<CommandOutput, RegistryError> {
146	        self.run_in(program, args, &self.cwd)
147	    }
148	
149	    fn run_in(&self, program: &str, args: &[&str], cwd: &std::path::Path) -> Result<CommandOutput, RegistryError> {
150	        self.runner
151	            .run_with_timeout(program, args, cwd, Duration::from_secs(PUBLISH_TIMEOUT_SECS))
152	            .map_err(|e| RegistryError::Other(e.to_string()))
153	    }
154	
155	    /// For an internal existence/probe check, not a real publish action --
156	    /// see [`callisto_model::CommandRunner::run_quiet`]. Its stderr is
157	    /// expected to look like a failure on the common case (e.g. `npm view`
158	    /// against an unpublished package), so it must not stream live.
159	    fn run_quiet(&self, program: &str, args: &[&str]) -> Result<CommandOutput, RegistryError> {
160	        self.runner
161	            .run_quiet(program, args, &self.cwd, Duration::from_secs(PUBLISH_TIMEOUT_SECS))
162	            .map_err(|e| RegistryError::Other(e.to_string()))
163	    }
164	
165	    // ---- Cargo / crates.io -------------------------------------------
166	
167	    /// Publishes a crate via `cargo publish`.
168	    ///
169	    /// When `registry` is `Some`, `--registry <name>` is appended so that
170	    /// private registries (e.g. Cloudsmith, Artifactory) are targeted instead
171	    /// of crates.io.
172	    fn cargo_publish(&self, package: &PackageId, registry: Option<&str>) -> Result<PublishOutcome, RegistryError> {
173	        if package.name().starts_with('-') {
174	            return Err(RegistryError::Other(format!(
175	                "invalid package name `{}`: names may not begin with '-' (possible flag injection)",
176	                package.name()
177	            )));
178	        }
179	
180	        // Pre-publish version sanity check: if load_plan provided a package
181	        // directory, read the on-disk Cargo.toml and verify its version matches
182	        // the planned version before invoking `cargo publish`. This catches the
183	        // common mistake of running `callisto publish` without first running
184	        // `callisto version`, which would silently publish the old version.
185	        if let (Some(pkg_dir), Some(planned)) = (
186	            self.cargo_pkg_dir.get(package.name()),
187	            self.cargo_planned_version.get(package.name()),
188	        ) {
189	            let manifest_path = self.cwd.join(pkg_dir).join("Cargo.toml");
190	            // Parse only the [package].version field — no need for full CST.
191	            // Use a permissive `toml::Value` intermediate rather than
192	            // deserializing straight into `String`: `version.workspace = true`
193	            // (Cargo's workspace-version-inheritance syntax) parses `version`
194	            // as a table, not a string, and a direct `String` deserialization
195	            // would fail with "invalid type: map, expected a string" on every
196	            // crate using that pattern.
197	            let contents = std::fs::read_to_string(&manifest_path).map_err(|e| {
198	                RegistryError::Other(format!(
199	                    "could not read `{}` for pre-publish version check: {e}. \
200	                         Ensure the package_dir in the publish plan points to the \
201	                         individual crate directory, not the workspace root.",
202	                    manifest_path.display(),
203	                ))
204	            })?;
205	            let parsed = toml::from_str::<toml::Value>(&contents).map_err(|e| {
206	                RegistryError::Other(format!(
207	                    "could not parse `{}` for pre-publish version check: {e}. \
208	                     The file must contain a [package].version field. \
209	                     If this is a workspace Cargo.toml, set package_dir to the \
210	                     individual crate subdirectory instead.",
211	                    manifest_path.display(),
212	                ))
213	            })?;
214	            let version_value = parsed.get("package").and_then(|p| p.get("version")).ok_or_else(|| {
215	                RegistryError::Other(format!(
216	                    "could not find [package].version in `{}` for pre-publish version check. \
217	                     The file must contain a [package].version field. \
218	                     If this is a workspace Cargo.toml, set package_dir to the \
219	                     individual crate subdirectory instead.",
220	                    manifest_path.display(),
221	                ))
222	            })?;
223	            let on_disk = if let Some(s) = version_value.as_str() {
224	                s.to_string()
225	            } else if version_value.get("workspace").and_then(|w| w.as_bool()) == Some(true) {
226	                let root_manifest_path = self.cwd.join("Cargo.toml");
227	                let resolver = WorkspaceCargoResolver::load(&root_manifest_path).map_err(|e| {
228	                    RegistryError::Other(format!(
229	                        "`{}` has version.workspace = true but the workspace root `{}` \
230	                             could not be loaded to resolve it: {e}",
231	                        manifest_path.display(),
232	                        root_manifest_path.display(),
233	                    ))
234	                })?;
235	                let ws_version = resolver
236	                    .workspace_version()
237	                    .map_err(|e| {
238	                        RegistryError::Other(format!(
239	                            "could not resolve [workspace.package].version from `{}` \
240	                             for `{}`: {e}",
241	                            root_manifest_path.display(),
242	                            manifest_path.display(),
243	                        ))
244	                    })?
245	                    .ok_or_else(|| {
246	                        RegistryError::Other(format!(
247	                            "`{}` has version.workspace = true but the workspace root `{}` \
248	                             has no [workspace.package].version",
249	                            manifest_path.display(),
250	                            root_manifest_path.display(),
251	                        ))
252	                    })?;
253	                ws_version.render().to_string()
254	            } else {
255	                return Err(RegistryError::Other(format!(
256	                    "could not parse [package].version in `{}` for pre-publish version \
257	                     check: expected a string or a `{{ workspace = true }}` table.",
258	                    manifest_path.display(),
259	                )));
260	            };
261	            let expected = planned.render();
262	            if on_disk != expected {
263	                return Err(RegistryError::Other(format!(
264	                    "version mismatch for `{}`: Cargo.toml on disk has version `{}` \
265	                     but the publish plan expects `{}`. \
266	                     Run `callisto version` first to write the new version to disk.",
267	                    package.name(),
268	                    on_disk,
269	                    expected,
270	                )));
271	            }
272	        }
273	
274	        let output = if let Some(reg) = registry {
275	            self.run(
276	                "cargo",
277	                &["publish", "-p", package.name(), "--locked", "--registry", reg],
278	            )?
279	        } else {
280	            self.run("cargo", &["publish", "-p", package.name(), "--locked"])?
281	        };
282	        classify_cargo_output(&output)
283	    }
284	
285	    // ---- npm ------------------------------------------------------------
286	
287	    fn npm_is_published(
288	        &self,
289	        package: &PackageId,
290	        version: &Version,
291	        registry: Option<&str>,
292	    ) -> Result<bool, RegistryError> {
293	        let spec = format!("{}@{}", package.name(), version.render());
294	        let output = if let Some(reg) = registry {
295	            self.run_quiet("npm", &["view", &spec, "--json", "--registry", reg])?
296	        } else {
297	            self.run_quiet("npm", &["view", &spec, "--json"])?
298	        };
299	
300	        if output.success() && !output.stdout_trimmed().is_empty() {
301	            return Ok(true);
302	        }
303	        if output.success() && output.stdout_trimmed().is_empty() {
304	            return Ok(false);
305	        }
306	
307	        let combined = combined_lower(&output);
308	        if combined.contains("e404")
309	            || combined.contains("etarget")
310	            || combined.contains("no matching version")
311	            || combined.contains("is not in this registry")
312	        {
313	            return Ok(false);
314	        }
315	
316	        if let Some(err) = detect_rate_limit(&combined) {
317	            return Err(err);
318	        }
319	        if let Some(err) = detect_auth_failure(&combined, &output.stderr) {
320	            return Err(err);
321	        }
322	
323	        // Ambiguous failure: don't silently treat as "not published" — a
324	        // false-negative here would cause a duplicate publish attempt.
325	        Err(RegistryError::Other(format!(
326	            "npm view failed ambiguously (exit {:?}): {}",
327	            output.exit_code,
328	            redact_stderr(output.stderr.trim())
329	        )))
330	    }
331	
332	    /// Detects the npm-compatible package manager from lockfiles in the
333	    /// workspace root (`self.cwd`) and returns the appropriate program name
334	    /// and base argument list for a publish command.
335	    ///
336	    /// Detection priority: pnpm > yarn > bun > npm (default).
337	    ///
338	    /// | Lockfile present   | Program | Base args                                    |
339	    /// |--------------------|---------|----------------------------------------------|
340	    /// | `pnpm-lock.yaml`   | `pnpm`  | `publish --filter <name>`                    |
341	    /// | `yarn.lock`        | `yarn`  | `workspace <name> npm publish`               |
342	    /// | `bun.lockb`/`.lock`| `bun`   | `publish`                                    |
343	    /// | (none)             | `npm`   | `publish --workspace <name>`                 |
344	    ///
345	    /// `tag` and `access` flags are appended after the base args by the caller
346	    /// ([`Self::npm_publish`]).
347	    fn build_npm_publish_command(
348	        &self,
349	        package_name: &str,
350	        tag: Option<&str>,
351	        access: Option<&str>,
352	        registry: Option<&str>,
353	    ) -> (String, Vec<String>) {
354	        let mut extra: Vec<String> = Vec::new();
355	        if let Some(t) = tag {
356	            extra.push("--tag".to_string());
357	            extra.push(t.to_string());
358	        }
359	        if let Some(av) = access {
360	            extra.push("--access".to_string());
361	            extra.push(av.to_string());
362	        }
363	        if let Some(reg) = registry {
364	            extra.push("--registry".to_string());
365	            extra.push(reg.to_string());
366	        }
367	
368	        if self.cwd.join("pnpm-lock.yaml").exists() {
369	            let mut args = vec![
370	                "publish".to_string(),
371	                "--filter".to_string(),
372	                package_name.to_string(),
373	                // pnpm ≥ 7 refuses to publish from a dirty working tree by
374	                // default. After `callisto version` stages manifest bumps,
375	                // the tree is always dirty until the operator commits, so
376	                // we must bypass the git-status check here.
377	                "--no-git-checks".to_string(),
378	            ];
379	            args.extend(extra);
380	            return ("pnpm".to_string(), args);
381	        }
382	
383	        if self.cwd.join("yarn.lock").exists() {
384	            let mut args = vec![
385	                "workspace".to_string(),
386	                package_name.to_string(),
387	                "npm".to_string(),
388	                "publish".to_string(),
389	            ];
390	            args.extend(extra);
391	            return ("yarn".to_string(), args);
392	        }
393	
394	        // bun.lockb is the legacy binary lockfile format; bun.lock (text) is
395	        // written by Bun >= 1.1.1. Both signal a bun-managed workspace.
396	        if self.cwd.join("bun.lockb").exists() || self.cwd.join("bun.lock").exists() {
397	            let mut args = vec!["publish".to_string()];
398	            args.extend(extra);
399	            return ("bun".to_string(), args);
400	        }
401	
402	        // Default: npm
403	        let mut args = vec![
404	            "publish".to_string(),
405	            "--workspace".to_string(),
406	            package_name.to_string(),
407	        ];
408	        args.extend(extra);
409	        ("npm".to_string(), args)
410	    }
411	
412	    /// Publishes an npm package using the workspace package manager detected
413	    /// from lockfiles in the workspace root (`self.cwd`).
414	    ///
415	    /// - `tag`: when `Some`, appends `--tag <tag>` (e.g. `"next"` for pre-releases).
416	    ///   Without this, the package manager uses the implicit `"latest"` dist-tag.
417	    /// - `access`: when `Some(NpmAccess::Public)`, appends `--access public`;
418	    ///   when `Some(NpmAccess::Restricted)`, appends `--access restricted`;
419	    ///   when `None`, omits `--access` entirely so the package manager applies
420	    ///   its ecosystem default (`restricted` for `@scoped/packages`, `public`
421	    ///   for unscoped).
422	    fn npm_publish(
423	        &self,
424	        package: &PackageId,
425	        tag: Option<&str>,
426	        access: Option<&NpmAccess>,
427	        registry: Option<&str>,
428	    ) -> Result<PublishOutcome, RegistryError> {
429	        if package.name().starts_with('-') {
430	            return Err(RegistryError::Other(format!(
431	                "invalid package name `{}`: names may not begin with '-' (possible flag injection)",
432	                package.name()
433	            )));
434	        }
435	        let access_value = access.map(|a| match a {
436	            NpmAccess::Public => "public",
437	            NpmAccess::Restricted => "restricted",
438	        });
439	        let (program, args_owned) = self.build_npm_publish_command(package.name(), tag, access_value, registry);
440	        let args_refs: Vec<&str> = args_owned.iter().map(|s| s.as_str()).collect();
441	
442	        // bun publish must run from the package directory — it has no
443	        // --filter or --workspace flag to target a named package. All other
444	        // package managers (pnpm --filter, yarn workspace, npm --workspace)
445	        // run from the workspace root and select the package by name.
446	        let effective_cwd = if program == "bun" {
447	            self.npm_pkg_dir
448	                .get(package.name())
449	                .map(|rel| self.cwd.join(rel))
450	                .unwrap_or_else(|| self.cwd.clone())
451	        } else {
452	            self.cwd.clone()
453	        };
454	
455	        let output = self.run_in(&program, &args_refs, &effective_cwd)?;
456	        classify_npm_publish_output(&output)
457	    }
458	
459	    // ---- PyPI -------------------------------------------------------------
460	
461	    /// Uploads a Python distribution to PyPI (or compatible index) via `twine
462	    /// upload --skip-existing dist/<normalized-name>-<version>*`.
463	    ///
464	    /// Package name is normalized to PEP 427 wheel-filename form (lowercased,
465	    /// `-`/`.` -> `_`) before building the glob. `twine` expands the glob
466	    /// internally -- no shell expansion, so the literal `*` is safe.
467	    ///
468	    /// `index: Some` inserts `--repository-url <url>` before the glob, to
469	    /// target a private index (Nexus/Artifactory PyPI proxy) instead of
470	    /// public PyPI.
471	    ///
472	    /// Output classification via [`classify_twine_output`]: `--skip-existing`'s
473	    /// "already exists" message -> [`PublishOutcome::AlreadyPublished`]; clean
474	    /// zero-exit with no skip message -> [`PublishOutcome::Published`];
475	    /// rate-limit/auth signals -> matching [`RegistryError`] variants;
476	    /// everything else -> [`RegistryError::Other`].
477	    fn pypi_publish(
478	        &self,
479	        package: &PackageId,
480	        version: &Version,
481	        index: Option<&str>,
482	    ) -> Result<PublishOutcome, RegistryError> {
483	        if package.name().starts_with('-') {
484	            return Err(RegistryError::Other(format!(
485	                "invalid package name `{}`: names may not begin with '-' (possible flag injection)",
486	                package.name()
487	            )));
488	        }
489	        let normalized = normalize_pypi_package_name(package.name());
490	        let pattern = format!("dist/{normalized}-{}*", version.render());
491	
492	        // Both build and upload run from the package directory so that `dist/`
493	        // resolves to the package's own dist/ folder. When no package_dir was
494	        // stored by load_plan (e.g. tests that call this method directly),
495	        // fall back to the workspace root.
496	        let pkg_cwd = self
497	            .pypi_pkg_dir
498	            .get(package.name())
499	            .map(|rel| self.cwd.join(rel))
500	            .unwrap_or_else(|| self.cwd.clone());
501	
502	        // Build step (spec §8.3): produce the sdist and wheel before uploading.
503	        // Build failures are not transient registry errors — do NOT retry them.
504	        let build_out = self.run_in(
505	            "python",
506	            &["-m", "build", "--sdist", "--wheel", "--outdir", "dist/"],
507	            &pkg_cwd,
508	        )?;
509	        if !build_out.success() {
510	            return Err(RegistryError::Other(format!(
511	                "python -m build failed for `{}` (exit {:?}): {}",
512	                package.name(),
513	                build_out.exit_code,
514	                redact_stderr(build_out.stderr.trim())
515	            )));
516	        }
517	
518	        let output = if let Some(idx) = index {
519	            self.run_in(
520	                "twine",
521	                &["upload", "--skip-existing", "--repository-url", idx, &pattern],
522	                &pkg_cwd,
523	            )?
524	        } else {
525	            self.run_in("twine", &["upload", "--skip-existing", &pattern], &pkg_cwd)?
526	        };
527	        classify_twine_output(&output)
528	    }
529	}
