605	// ---- shared classification helpers ---------------------------------------
606	
607	fn combined_lower(output: &CommandOutput) -> String {
608	    format!("{}\n{}", output.stdout, output.stderr).to_lowercase()
609	}
610	
611	/// Looks for a `retry after <N>` mention in already-lowercased text and
612	/// parses `<N>` as a whole-second duration via the orchestrator's shared
613	/// [`parse_retry_after`] helper.
614	fn extract_retry_after_duration(text_lower: &str) -> Option<Duration> {
615	    const NEEDLE: &str = "retry after ";
616	    let idx = text_lower.find(NEEDLE)?;
617	    let rest = &text_lower[idx + NEEDLE.len()..];
618	    let token = rest.split_whitespace().next()?;
619	    let digits: String = token.chars().take_while(|c| c.is_ascii_digit()).collect();
620	    if digits.is_empty() {
621	        return None;
622	    }
623	    parse_retry_after(&digits)
624	}
625	
626	fn detect_rate_limit(text_lower: &str) -> Option<RegistryError> {
627	    // Match rate-limit signals with context, never on bare digits alone.
628	    // Bare "429" in cargo's compressed-size output ("429.1KiB compressed")
629	    // would otherwise trigger this — causing an infinite retry on unrelated
630	    // failures. Require at least one contextual phrase alongside any "429".
631	    let is_rate_limited = text_lower.contains("too many requests")
632	        || text_lower.contains("rate limit")
633	        || text_lower.contains("erate_limit")
634	        || (text_lower.contains("429")
635	            && (text_lower.contains("too many") || text_lower.contains("rate") || text_lower.contains("retry")));
636	    if is_rate_limited {
637	        let dur = extract_retry_after_duration(text_lower).unwrap_or(Duration::from_secs(
638	            crate::commands::publish::DEFAULT_RATE_LIMIT_WAIT_SECS,
639	        ));
640	        Some(RegistryError::RateLimited(dur))
641	    } else {
642	        None
643	    }
644	}
645	
646	/// Redacts known registry-credential env-var values and any URL userinfo
647	/// component from subprocess stderr before it's embedded in a
648	/// [`RegistryError`] -- registry CLIs (`cargo publish`, `npm publish`,
649	/// `twine upload`) can echo a credential verbatim in their own error
650	/// diagnostics on auth failure, and this text flows verbatim into the JSON
651	/// `PublishReport` and CI logs downstream.
652	fn redact_stderr(text: &str) -> String {
653	    redact_known_secrets(text, &known_credential_env_values(std::env::vars()))
654	}
655	
656	fn detect_auth_failure(text_lower: &str, raw_stderr: &str) -> Option<RegistryError> {
657	    // Match "401"/"403" with context, never on bare digits alone -- same
658	    // rationale as detect_rate_limit's guard against bare "429": a byte
659	    // count or elapsed-time figure in cargo's own packaging/build output
660	    // ("403129 bytes", "elapsed 4013ms") would otherwise misclassify an
661	    // unrelated failure as an auth failure.
662	    if (text_lower.contains("401") && text_lower.contains("auth"))
663	        || (text_lower.contains("403") && (text_lower.contains("auth") || text_lower.contains("forbidden")))
664	        || text_lower.contains("authentication")
665	        || text_lower.contains("not logged in")
666	        || text_lower.contains("invalid token")
667	        || text_lower.contains("forbidden")
668	    {
669	        Some(RegistryError::AuthFailed(redact_stderr(raw_stderr.trim())))
670	    } else {
671	        None
672	    }
673	}
674	
675	fn classify_cargo_output(output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
676	    let combined = combined_lower(output);
677	
678	    if combined.contains("already exists") || combined.contains("already uploaded") {
679	        return Ok(PublishOutcome::AlreadyPublished);
680	    }
681	    if output.success() {
682	        return Ok(PublishOutcome::Published);
683	    }
684	    if let Some(err) = detect_rate_limit(&combined) {
685	        return Err(err);
686	    }
687	    if let Some(err) = detect_auth_failure(&combined, &output.stderr) {
688	        return Err(err);
689	    }
690	    Err(RegistryError::Other(format!(
691	        "cargo publish failed (exit {:?}): {}",
692	        output.exit_code,
693	        redact_stderr(output.stderr.trim())
694	    )))
695	}
696	
697	fn classify_npm_publish_output(output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
698	    let combined = combined_lower(output);
699	
700	    if combined.contains("epublishconflict")
701	        || combined.contains("previously published")
702	        || combined.contains("cannot publish over")
703	        || combined.contains("e409")
704	        || combined.contains("409 conflict")
705	    {
706	        return Ok(PublishOutcome::AlreadyPublished);
707	    }
708	    if output.success() {
709	        return Ok(PublishOutcome::Published);
710	    }
711	    if let Some(err) = detect_rate_limit(&combined) {
712	        return Err(err);
713	    }
714	    if let Some(err) = detect_auth_failure(&combined, &output.stderr) {
715	        return Err(err);
716	    }
717	    Err(RegistryError::Other(format!(
718	        "npm publish failed (exit {:?}): {}",
719	        output.exit_code,
720	        redact_stderr(output.stderr.trim())
721	    )))
722	}
723	
724	/// Classifies combined `twine upload` output into a [`PublishOutcome`] or
725	/// [`RegistryError`].
726	///
727	/// Priority order (highest wins):
728	/// 1. `"already exist"` (from `--skip-existing`) without `"uploading"` →
729	///    [`PublishOutcome::AlreadyPublished`] (all artifacts skipped). Both
730	///    phrases present means at least one artifact was freshly uploaded →
731	///    `Published`. Handles `dist/` accumulating stale pre-release
732	///    artifacts: `dist/my_pkg-1.0.0*` matches both `my_pkg-1.0.0a0.whl`
733	///    (skipped) and `my_pkg-1.0.0.whl` (uploaded), producing mixed output.
734	/// 2. Zero exit code with no skip-only mention → [`PublishOutcome::Published`].
735	/// 3. Rate-limit signal (`429`, `too many requests`, `rate limit`) →
736	///    [`RegistryError::RateLimited`] with a parsed or default 60-second
737	///    retry-after duration.
738	/// 4. Auth-failure signal (`401`, `403`, `authentication`, etc.) →
739	///    [`RegistryError::AuthFailed`].
740	/// 5. Anything else → [`RegistryError::Other`].
741	fn classify_twine_output(output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
742	    let combined = combined_lower(output);
743	
744	    let has_skip = combined.contains("already exist");
745	    let has_upload = combined.contains("uploading");
746	    if has_skip && !has_upload {
747	        return Ok(PublishOutcome::AlreadyPublished);
748	    }
749	    if output.success() {
750	        return Ok(PublishOutcome::Published);
751	    }
752	    if let Some(err) = detect_rate_limit(&combined) {
753	        return Err(err);
754	    }
755	    if let Some(err) = detect_auth_failure(&combined, &output.stderr) {
756	        return Err(err);
757	    }
758	    Err(RegistryError::Other(format!(
759	        "twine upload failed (exit {:?}): {}",
760	        output.exit_code,
761	        redact_stderr(output.stderr.trim())
762	    )))
763	}
