1052	    /// tracking which one the underlying `CommandRunner` actually receives.
1053	    struct QuietTrackingRunner {
1054	        quiet_called: std::sync::atomic::AtomicBool,
1055	        live_called: std::sync::atomic::AtomicBool,
1056	        response: CommandOutput,
